/**
 * Pure tests for the crq repair-request builder.
 *
 * The oracle fixture is generated by `apps/crq-python/repair_request_vectors.py`
 * from the PRODUCTION Python `crq_repair.drivers.cq.fixer_body`. These tests
 * pin the legacy body bytes, the deliberate typed mapping (scanned operator
 * guidance moves to the op's trusted `instructions` field), the three Python
 * ValueError refusals, astral/escaping and whole-line anchor behaviour, the
 * binding and guidance gates, and the fact that the builder never measures the
 * op's 32768-unit invocation envelope. No process, filesystem write, clock,
 * git read or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  buildRepairRequest,
  legacyFixerBody,
  type BuildRepairRequestResult,
  type RepairBodyAnchor,
  type RepairRequestContext,
  type RepairRequestPrepared,
  type RepairRequestRefusal,
} from '../../../src/policy/crq/repairRequest.js';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';
import { atomicJsonText } from '../../../src/policy/crq/pythonJson.js';
import type { FixFindingBinding } from '../../../src/ops/review/fixFinding.js';
import type { FixFindingInput } from '../../../src/ops/review/fixFinding.js';

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/repair-request/cases.json',
  import.meta.url,
);
const fixture = asObject(parseJsonValue(readFileSync(FIXTURE_URL, 'utf8')));
const cases = asArray(fixture.get('cases')).map((entry) => asObject(entry));

const MARKER = '\nPinned current-source evidence (untrusted data):\n';
const JOB_ID = 'crq-revalidated-cb466c2a4e9f4881d7b6c47c-F1';

const CONTEXT: RepairRequestContext = {
  repo: 'example/repo',
  worktree: { path: '/work/crq-repair', branch: 'detached' },
  driver: { provider: 'zai', model: 'glm-5.3-flash' },
  budget: { maxOutputTokens: 8000, maxContextTokens: 9000, wallClockMs: 120_000 },
};

function asObject(value: JsonValue | undefined): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error('expected a JSON object');
  return value;
}

function asArray(value: JsonValue | undefined): JsonValue[] {
  if (!Array.isArray(value)) throw new Error('expected a JSON array');
  return value;
}

function asString(value: JsonValue | undefined): string {
  if (typeof value !== 'string') throw new Error('expected a JSON string');
  return value;
}

function asNumber(value: JsonValue | undefined): number {
  if (!(value instanceof JsonNumber) || value.kind !== 'int') {
    throw new Error('expected a JSON integer');
  }
  return Number(value.integer);
}

function asBoolean(value: JsonValue | undefined): boolean {
  if (typeof value !== 'boolean') throw new Error('expected a JSON boolean');
  return value;
}

function optionalString(value: JsonValue | undefined): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function caseNamed(name: string): JsonObject {
  const found = cases.find((candidate) => candidate.get('name') === name);
  if (found === undefined) throw new Error(`missing fixture case ${name}`);
  return found;
}

function bindingOf(c: JsonObject): FixFindingBinding {
  const binding = asObject(c.get('binding'));
  return {
    job: asString(binding.get('job')),
    sourceSha: asString(binding.get('sourceSha')),
    sourceBlobSha: asString(binding.get('sourceBlobSha')),
    findingSha256: asString(binding.get('findingSha256')),
    repairBase: asString(binding.get('repairBase')),
  };
}

function anchorOf(value: JsonValue | undefined): RepairBodyAnchor {
  const anchor = asObject(value);
  return {
    lineStart: asNumber(anchor.get('lineStart')),
    lineEnd: asNumber(anchor.get('lineEnd')),
    incomplete: asBoolean(anchor.get('incomplete')),
    lineCount: asNumber(anchor.get('lineCount')),
  };
}

function refusalFor(message: string): RepairRequestRefusal {
  switch (message) {
    case 'fixer finding, provenance and anchor exceed item body budget':
      return 'item-body-budget-exceeded';
    case 'fixer source excerpt is incomplete or malformed':
      return 'source-excerpt-incomplete-or-malformed';
    case 'fixer source anchor or provenance unavailable':
      return 'source-anchor-provenance-unavailable';
    default:
      throw new Error(`unexpected Python refusal: ${message}`);
  }
}

function preparedOf(c: JsonObject, guidance?: string): RepairRequestPrepared {
  return {
    job: asObject(c.get('job')),
    snapshot: asObject(c.get('snapshot')),
    binding: bindingOf(c),
    ...(guidance === undefined ? {} : { scannedGuidance: guidance }),
  };
}

function buildFor(
  c: JsonObject,
  options: { readonly guidance?: string; readonly context?: RepairRequestContext } = {},
): BuildRepairRequestResult {
  return buildRepairRequest({
    prepared: preparedOf(c, options.guidance),
    context: options.context ?? CONTEXT,
  });
}

function buildWithJob(
  c: JsonObject,
  job: JsonObject,
  options: {
    readonly guidance?: string;
    readonly context?: RepairRequestContext;
    readonly binding?: FixFindingBinding;
  } = {},
): BuildRepairRequestResult {
  return buildRepairRequest({
    prepared: {
      job,
      snapshot: asObject(c.get('snapshot')),
      binding: options.binding ?? bindingOf(c),
      ...(options.guidance === undefined ? {} : { scannedGuidance: options.guidance }),
    },
    context: options.context ?? CONTEXT,
  });
}

function withField(object: JsonObject, key: string, value: JsonValue): JsonObject {
  const entries = object.entries.map(
    ([name, existing]) => [name, name === key ? value : existing] as const,
  );
  if (!object.has(key)) entries.push([key, value]);
  return new JsonObject(entries);
}

function withoutField(object: JsonObject, key: string): JsonObject {
  return new JsonObject(object.entries.filter(([name]) => name !== key));
}

function withOperatorGuidance(c: JsonObject, value: JsonValue): JsonObject {
  const job = asObject(c.get('job'));
  const revalidation = asObject(job.get('revalidation'));
  return withField(job, 'revalidation', withField(revalidation, 'fix_instructions', value));
}

function typedOf(c: JsonObject): {
  readonly instructions?: string;
  readonly body?: string;
  readonly error?: string;
  readonly anchor?: RepairBodyAnchor;
} {
  const typed = asObject(c.get('typed'));
  const anchor = typed.get('anchor');
  const instructions = optionalString(typed.get('instructions'));
  const body = optionalString(typed.get('body'));
  const error = optionalString(typed.get('error'));
  return {
    ...(instructions === undefined ? {} : { instructions }),
    ...(body === undefined ? {} : { body }),
    ...(error === undefined ? {} : { error }),
    ...(anchor === null || anchor === undefined ? {} : { anchor: anchorOf(anchor) }),
  };
}

function packedOf(body: string): JsonObject {
  const at = body.lastIndexOf(MARKER);
  if (at < 0) throw new Error('body has no pinned-source marker');
  return asObject(parseJsonValue(body.slice(at + MARKER.length)));
}

/** The flat, already-normalized item shape the builder produces. */
function itemOf(input: FixFindingInput): {
  readonly id: string;
  readonly path: string | null;
  readonly line: number | null;
  readonly body: string;
  readonly comments: readonly unknown[];
} {
  if (!('body' in input.item)) throw new Error('expected a flat review item');
  return input.item;
}

describe('legacy fixer_body matches the production Python oracle', () => {
  for (const c of cases) {
    const name = asString(c.get('name'));
    test(name, () => {
      const result = legacyFixerBody(asObject(c.get('job')));
      const error = optionalString(c.get('error'));
      if (error !== undefined) {
        expect(result).toEqual({ ok: false, refusal: refusalFor(error) });
        return;
      }
      expect(result.ok).toBe(true);
      if (!result.ok) return;
      expect(result.body).toBe(asString(c.get('body')));
      expect(result.anchor).toEqual(anchorOf(c.get('anchor')));
    });
  }
});

describe('typed new-op mapping extracts scanned operator guidance', () => {
  for (const c of cases) {
    const typed = typedOf(c);
    if (typed.body === undefined) continue;
    const name = asString(c.get('name'));
    test(name, () => {
      const result = buildFor(c, {
        ...(typed.instructions === undefined ? {} : { guidance: typed.instructions }),
      });
      expect(result.ok).toBe(true);
      if (!result.ok) return;
      expect(itemOf(result.value.input).body).toBe(typed.body);
      expect(result.value.anchor).toEqual(typed.anchor);
      expect(result.value.instructionsChars).toBe(
        typed.instructions === undefined ? 0 : typed.instructions.length,
      );
      if (typed.instructions !== undefined) {
        expect(result.value.input.instructions).toBe(typed.instructions);
        expect(itemOf(result.value.input).body).not.toContain('Operator fix guidance');
        expect(itemOf(result.value.input).body).not.toContain(
          'Retry guidance from the previous attempt',
        );
      } else {
        expect(result.value.input.instructions).toBeUndefined();
      }
    });
  }

  test('retry guidance stays in the body when no operator guidance was scanned', () => {
    const c = caseNamed('retry-guidance');
    const result = buildFor(c);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.value.input.instructions).toBeUndefined();
    expect(itemOf(result.value.input).body).toContain('Retry guidance from the previous attempt');
    expect(itemOf(result.value.input).body).toContain('Prior attempt guidance.');
  });

  test('body matches Python fixer_body for the same job with guidance removed', () => {
    // The fixture's typed body is generated by running production
    // `fixer_body` on the job after both guidance fields are removed.
    const c = caseNamed('operator-and-retry-guidance');
    const typed = typedOf(c);
    expect(typed.body).toBeDefined();
    const result = buildFor(c, {
      ...(typed.instructions === undefined ? {} : { guidance: typed.instructions }),
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(itemOf(result.value.input).body).toBe(typed.body);
  });
});

describe('typed body refusals keep Python order and never truncate', () => {
  const bodyRefusalCases = [
    'anchor-too-large',
    'malformed-excerpt',
    'path-mismatch',
    'anchor-line-out-of-range',
    'line-bool',
    'start-bool',
    'source-not-string',
  ];
  for (const name of bodyRefusalCases) {
    test(name, () => {
      const c = caseNamed(name);
      const typed = typedOf(c);
      const result = buildFor(c, {
        ...(typed.instructions === undefined ? {} : { guidance: typed.instructions }),
      });
      expect(result).toEqual({
        ok: false,
        refusal: refusalFor(asString(typed.error)),
      });
      expect('body' in result).toBe(false);
    });
  }

  test('provenance gaps are binding mismatches before body composition', () => {
    for (const name of ['provenance-missing', 'provenance-empty', 'combined-order']) {
      expect(buildFor(caseNamed(name))).toEqual({ ok: false, refusal: 'binding-mismatch' });
    }
  });

  test('an oversized anchor refuses instead of returning a clipped body', () => {
    const result = legacyFixerBody(asObject(caseNamed('anchor-too-large').get('job')));
    expect(result).toEqual({ ok: false, refusal: 'item-body-budget-exceeded' });
  });
});

describe('whole anchor lines and the 8000 UTF-16 body bound', () => {
  test('a full source excerpt keeps every whole line', () => {
    const body = asString(caseNamed('full-source-anchor').get('body'));
    const packed = packedOf(body);
    expect(packed.get('line_start')).toEqual(JsonNumber.int(1));
    expect(packed.get('line_end')).toEqual(JsonNumber.int(10));
    expect(packed.get('incomplete')).toBe(false);
    const lines = asString(packed.get('source')).split('\n');
    expect(lines).toHaveLength(10);
    expect(lines.every((line, offset) => line.startsWith(`${offset + 1}: `))).toBe(true);
  });

  test('expansion stops between whole lines at the exact Python boundary', () => {
    const c = caseNamed('expand-to-bound');
    const body = asString(c.get('body'));
    expect(body.length).toBeLessThanOrEqual(8000);
    const packed = packedOf(body);
    const start = asNumber(packed.get('line_start'));
    const end = asNumber(packed.get('line_end'));
    expect(start).toBe(31);
    expect(end).toBe(89);
    const lines = asString(packed.get('source')).split('\n');
    expect(lines).toHaveLength(end - start + 1);
    expect(lines.every((line, offset) => line.startsWith(`${start + offset}: `))).toBe(true);
  });

  test('every valid typed body respects the bound', () => {
    for (const c of cases) {
      const typed = typedOf(c);
      if (typed.body === undefined) continue;
      const result = buildFor(c, {
        ...(typed.instructions === undefined ? {} : { guidance: typed.instructions }),
      });
      expect(result.ok).toBe(true);
      if (!result.ok) continue;
      expect(result.value.bodyChars).toBeLessThanOrEqual(8000);
      expect(result.value.bodyChars).toBe(itemOf(result.value.input).body.length);
    }
  });
});

describe('astral characters and JSON escaping match json.dumps defaults', () => {
  test('the packed source uses ASCII escapes and default separators', () => {
    const body = asString(caseNamed('astral-and-escapes').get('body'));
    expect(body).toContain('"source_sha": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"');
    expect(body).toContain(', "source_blob_sha": ');
    expect(body).toContain('\\u96ea');
    expect(body).toContain('\\ud83d\\ude00');
    expect(body).toContain('\\u0001');
    const packed = packedOf(body);
    expect(asString(packed.get('source'))).toContain('雪 😀');
  });

  test('the finding body and mechanical evidence are not truncated', () => {
    const c = caseNamed('astral-and-escapes');
    const body = asString(c.get('body'));
    expect(body.startsWith('Full finding 😀\nwith two lines and "quotes"')).toBe(true);
    expect(body).toContain('Mechanical 😀 evidence\ttab');
  });
});

describe('binding, guidance and context gates', () => {
  const base = caseNamed('simple-no-guidance');
  const binding = bindingOf(base);

  test('a binding with a missing field is invalid', () => {
    const incomplete = { ...binding } as Partial<FixFindingBinding>;
    delete incomplete.findingSha256;
    expect(
      buildWithJob(base, asObject(base.get('job')), {
        binding: incomplete as FixFindingBinding,
      }),
    ).toEqual({ ok: false, refusal: 'binding-invalid' });
  });

  test('binding grammar is enforced', () => {
    for (const patch of [
      { job: '' },
      { sourceSha: 'A'.repeat(40) },
      { sourceBlobSha: 'c'.repeat(39) },
      { findingSha256: 'D'.repeat(64) },
      { repairBase: 'not-a-sha' },
    ]) {
      expect(
        buildWithJob(base, asObject(base.get('job')), {
          binding: { ...binding, ...patch },
        }),
      ).toEqual({ ok: false, refusal: 'binding-invalid' });
    }
  });

  test('binding consistency with the prepared identity is checked, not git', () => {
    for (const patch of [
      { job: 'crq-other-F1' },
      { sourceSha: 'b'.repeat(40) },
      { sourceBlobSha: 'e'.repeat(40) },
      { findingSha256: 'f'.repeat(64) },
      { repairBase: 'b'.repeat(40) },
    ]) {
      expect(
        buildWithJob(base, asObject(base.get('job')), {
          binding: { ...binding, ...patch },
        }),
      ).toEqual({ ok: false, refusal: 'binding-mismatch' });
    }
  });

  test('a consistent request still carries an unverified caller binding', () => {
    const result = buildFor(base);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.value.bindingStatus).toBe('caller-unverified');
    expect(result.value.input.binding).toEqual(binding);
  });

  test('operator guidance must match the already-scanned copy exactly', () => {
    const c = caseNamed('operator-guidance');
    const operator = typedOf(c).instructions as string;
    expect(buildFor(c)).toEqual({ ok: false, refusal: 'guidance-unverified' });
    expect(buildFor(c, { guidance: 'different guidance' })).toEqual({
      ok: false,
      refusal: 'guidance-unverified',
    });
    expect(buildFor(c, { guidance: operator })).toMatchObject({ ok: true });
  });

  test('guidance without a prepared provenance is refused', () => {
    expect(buildFor(base, { guidance: 'unrequested guidance' })).toEqual({
      ok: false,
      refusal: 'guidance-unverified',
    });
  });

  test('astral guidance that passes Python but exceeds the op UTF-16 bound is refused', () => {
    const c = caseNamed('simple-no-guidance');
    const guidance = '😀'.repeat(2000);
    const job = withOperatorGuidance(c, guidance);
    expect(buildWithJob(c, job, { guidance })).toEqual({
      ok: false,
      refusal: 'instructions-dispatch-incompatible',
    });
  });

  test('blank, NUL and oversized guidance are refused', () => {
    const c = caseNamed('simple-no-guidance');
    for (const guidance of ['   ', 'bad\u0000text', 'x'.repeat(2001)]) {
      const job = withOperatorGuidance(c, guidance);
      expect(buildWithJob(c, job, { guidance })).toEqual({
        ok: false,
        refusal: 'instructions-dispatch-incompatible',
      });
    }
  });

  test('request context requires non-empty worktree, driver, repo and prompt override', () => {
    const badContexts: RepairRequestContext[] = [
      { ...CONTEXT, worktree: { path: '', branch: 'detached' } },
      { ...CONTEXT, worktree: { path: '/work', branch: '' } },
      { ...CONTEXT, driver: { provider: '', model: 'm' } },
      { ...CONTEXT, driver: { provider: 'p', model: '' } },
      { ...CONTEXT, repo: '' },
      { ...CONTEXT, promptOverride: '' },
    ];
    for (const context of badContexts) {
      expect(buildFor(base, { context })).toEqual({
        ok: false,
        refusal: 'request-context-invalid',
      });
    }
  });
});

describe('typed input mapping', () => {
  test('uses the prepared job id and the normalized item shape', () => {
    const result = buildFor(caseNamed('simple-no-guidance'));
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const input = result.value.input;
    expect(result.value.status).toBe('request-built');
    expect(result.value.itemId).toBe(JOB_ID);
    expect(input.item).toEqual({
      id: JOB_ID,
      path: 'src/lock.ts',
      line: 2,
      body: asString(caseNamed('simple-no-guidance').get('body')),
      comments: [],
    });
    expect(input.item).not.toHaveProperty('kind');
    expect(input.item).not.toHaveProperty('finding');
    expect(input.repo).toBe('example/repo');
    expect(input.pr).toBe(1);
    expect(input.worktree).toEqual({ path: '/work/crq-repair', branch: 'detached' });
    expect(input.driver).toEqual({ provider: 'zai', model: 'glm-5.3-flash' });
    expect(input.budget).toEqual(CONTEXT.budget);
  });

  test('omits repository and budget when the caller does not supply them', () => {
    const context: RepairRequestContext = {
      worktree: CONTEXT.worktree,
      driver: CONTEXT.driver,
    };
    const result = buildFor(caseNamed('simple-no-guidance'), { context });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.value.input).not.toHaveProperty('repo');
    expect(result.value.input).not.toHaveProperty('budget');
  });

  test('passes a caller prompt override through without measuring it', () => {
    const promptOverride = 'x'.repeat(30_000);
    const result = buildFor(caseNamed('simple-no-guidance'), {
      context: { ...CONTEXT, promptOverride },
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.value.input.promptOverride).toBe(promptOverride);
  });

  test('includes pr only when it is a positive Python int', () => {
    const c = caseNamed('simple-no-guidance');
    const job = asObject(c.get('job'));
    for (const [value, expected] of [
      [JsonNumber.int(0), undefined],
      [JsonNumber.int(-1), undefined],
      [JsonNumber.float(1), undefined],
      [true, undefined],
      [JsonNumber.int(2), 2],
    ] as const) {
      const result = buildWithJob(c, withField(job, 'pr', value));
      expect(result.ok).toBe(true);
      if (!result.ok) continue;
      expect(result.value.input.pr).toBe(expected);
    }
  });

  test('remaining gates name every effect and the op-owned invocation bound', () => {
    const baseResult = buildFor(caseNamed('simple-no-guidance'));
    expect(baseResult.ok).toBe(true);
    if (!baseResult.ok) return;
    expect(baseResult.value.remainingGates).toEqual([
      'caller-binding-revalidation',
      'source-tip-revalidation',
      'source-blob-revalidation',
      'source-secret-scan-confirmation',
      'invocation-size-bound',
      'enqueue-dispatch',
      'harvest-disposition',
    ]);

    const operatorGuidance = typedOf(caseNamed('operator-guidance')).instructions;
    const operatorResult = buildFor(
      caseNamed('operator-guidance'),
      operatorGuidance === undefined ? {} : { guidance: operatorGuidance },
    );
    expect(operatorResult.ok).toBe(true);
    if (!operatorResult.ok) return;
    expect(operatorResult.value.remainingGates).toEqual([
      'caller-binding-revalidation',
      'source-tip-revalidation',
      'source-blob-revalidation',
      'source-secret-scan-confirmation',
      'guidance-secret-scan-confirmation',
      'invocation-size-bound',
      'enqueue-dispatch',
      'harvest-disposition',
    ]);
  });

  test('does not duplicate the op 32768-unit serialized envelope check', () => {
    const promptOverride = 'x'.repeat(40_000);
    const result = buildFor(caseNamed('simple-no-guidance'), {
      context: { ...CONTEXT, promptOverride },
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    // The exact input already exceeds the op envelope; the builder must still
    // build it and leave the bound to the op (`invocation-size-bound`).
    expect(JSON.stringify(result.value.input).length).toBeGreaterThan(32_768);
    expect(result.value.remainingGates).toContain('invocation-size-bound');
  });
});

describe('refusal vocabulary stays internal and evidence is retained', () => {
  test('a missing snapshot is unreadable, not an empty body', () => {
    const job = withoutField(
      asObject(caseNamed('simple-no-guidance').get('job')),
      'source_snapshot',
    );
    expect(legacyFixerBody(job)).toEqual({
      ok: false,
      refusal: 'source-snapshot-unreadable',
    });
  });

  test('a non-string mechanical evidence value is refused', () => {
    const c = caseNamed('simple-no-guidance');
    const job = withField(asObject(c.get('job')), 'mechanical_evidence', JsonNumber.int(1));
    expect(legacyFixerBody(job)).toEqual({
      ok: false,
      refusal: 'mechanical-evidence-invalid',
    });
    expect(buildWithJob(c, job)).toEqual({
      ok: false,
      refusal: 'mechanical-evidence-invalid',
    });
  });

  test('missing mechanical evidence keeps its exact empty prefix', () => {
    const job = withoutField(
      asObject(caseNamed('simple-no-guidance').get('job')),
      'mechanical_evidence',
    );
    const result = legacyFixerBody(job);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.body).toContain('\nMechanical evidence / judge rationale: \n');
  });

  test('building never mutates the prepared job or snapshot', () => {
    const c = caseNamed('astral-and-escapes');
    const job = asObject(c.get('job'));
    const snapshot = asObject(c.get('snapshot'));
    const beforeJob = atomicJsonText(job);
    const beforeSnapshot = atomicJsonText(snapshot);
    const guidance = typedOf(c).instructions;
    legacyFixerBody(job);
    buildFor(c, { ...(guidance === undefined ? {} : { guidance }) });
    expect(atomicJsonText(job)).toBe(beforeJob);
    expect(atomicJsonText(snapshot)).toBe(beforeSnapshot);
  });
});
